// Shared path helpers: where the two documentation trees live and how a Markdown file maps
// to a Starlight route id.
//
// The site renders two trees side by side, each under its own URL prefix:
//   /current/...   <- ../build/before  (old category layout, generated by scripts/build_all.sh)
//   /proposed/...  <- ../docs          (new hierarchical tree)
// Both trees share ../docs/assets (build/before/assets is a symlink to it), served at /assets.
import path from 'node:path';
import { fileURLToPath } from 'node:url';

// astro.config.mjs (loaded unbundled, so import.meta.url is right) records the site folder in
// the environment; code that Vite bundles for prerendering (pages, components, middleware)
// would otherwise resolve import.meta.url to a chunk under dist/.
export const SITE_DIR = process.env.WP_DOCS_SITE_DIR ?? path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
process.env.WP_DOCS_SITE_DIR ??= SITE_DIR;
export const REPO_DIR = path.resolve(SITE_DIR, '..');
export const DOCS_DIR = path.join(REPO_DIR, 'docs');
export const BEFORE_DIR = path.join(REPO_DIR, 'build/before');
export const DATA_DIR = path.join(REPO_DIR, 'data');
export const ASSETS_DIR = path.join(DOCS_DIR, 'assets');

const GITHUB = 'https://github.com/ndiego/wp-documentation-migration';

/**
 * The two trees. `src` is the folder relative to the repo root (= the glob loader's base),
 * `prefix` the route prefix / id prefix.
 */
export const TREES = [
	{
		key: 'current',
		prefix: 'current',
		src: 'build/before',
		dir: BEFORE_DIR,
		label: 'Current structure',
		short: 'Current',
		description: 'the category layout live on wordpress.org/documentation today',
		// Read-only: the old layout as committed at the before-restructure tag.
		sourceUrl: (rel) => `${GITHUB}/blob/before-restructure/docs/${rel}`,
		sourceLabel: 'View source (before-restructure tag)',
	},
	{
		key: 'proposed',
		prefix: 'proposed',
		src: 'docs',
		dir: DOCS_DIR,
		label: 'Proposed structure',
		short: 'Proposed',
		description: 'the hierarchical tree proposed in this repository',
		sourceUrl: (rel) => `${GITHUB}/edit/restructure/docs/${rel}`,
		sourceLabel: 'Edit on GitHub',
	},
];
export const TREE = Object.fromEntries(TREES.map((t) => [t.key, t]));

/** absolute file path -> tree (or undefined) */
export function treeForFile(abs) {
	const p = path.resolve(abs);
	return TREES.find((t) => p.startsWith(t.dir + path.sep));
}

/** route id / pathname -> tree (or undefined) */
export function treeForId(id) {
	const first = id.replace(/^\/+/, '').split('/')[0];
	return TREE[first];
}

/**
 * tree-relative file path -> path id within the tree (no prefix)
 *   customization/block-editor/blocks-list.md -> customization/block-editor/blocks-list
 *   customization/README.md                    -> customization
 *   README.md                                  -> ''   (the tree's root)
 */
export function idFromDocsPath(rel) {
	const p = rel.split(path.sep).join('/').replace(/\.md$/i, '');
	if (/(^|\/)readme$/i.test(p)) return p.replace(/\/?readme$/i, '').toLowerCase();
	return p.toLowerCase();
}

/** tree + tree-relative file path -> entry id, e.g. proposed/overview, current */
export function treeId(tree, rel) {
	const inner = idFromDocsPath(rel);
	return inner ? `${tree.prefix}/${inner}` : tree.prefix;
}

/**
 * glob-loader entry (relative to the repo root) -> entry id
 *   docs/overview/README.md                  -> proposed/overview
 *   build/before/customization/x.md          -> current/customization/x
 */
export function idFromRepoPath(entry) {
	const e = entry.split(path.sep).join('/');
	for (const t of TREES) {
		if (e.startsWith(t.src + '/')) return treeId(t, e.slice(t.src.length + 1));
	}
	throw new Error(`[paths] file outside both trees: ${entry}`);
}

/** entry id -> site URL path */
export function routeFromId(id) {
	return id === 'index' || id === '' ? '/' : `/${id}/`;
}
